package com.integration.service.impl;

import com.integration.constant.LeadSquaredApiConstants;
import com.integration.model.leadsquared.*;
import com.integration.repository.*;
import com.integration.service.APILoggerService;
import com.integration.service.LeadSquaredService;
import com.integration.service.RazorPayService;
import com.integration.util.RestUtils;
import lombok.RequiredArgsConstructor;
import lombok.extern.log4j.Log4j2;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.*;
import org.springframework.stereotype.Service;

import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.*;

@Service
@Log4j2
@RequiredArgsConstructor
public class LeadSquaredServiceImpl implements LeadSquaredService {

    private final LsqOwnerRepository lsqOwnerRepository;
    private final LsqRazorpayRepository lsqRazorpayRepository;
    private final LeadsquaredUserRepository leadsquaredUserRepository;
    private final LsqPaymentLinkRepository lsqPaymentLinkRepository;
    private final RestUtils restUtils;
    private final APILoggerService apiLoggerService;

    @Value("${lsq.activity.url}")
    String lsqActivityUrl;

    @Value("${lsq.secret-key}")
    String lsqSecretKey;

    @Value("${lsq.access-key}")
    String lsqAccessKey;

    @Value("${lsq.owners.url}")
    String lsqOwnersUrl;

    @Value("${lsq.lead.get-by-id.url}")
    String lsqGetLeadByIdUrl;
    private final RazorPayService razorPayService;

    public boolean processLsqRazorpayActivity(Date fromDate, Date toDate) throws Exception {
        String fetchActivitiesUrl = lsqActivityUrl;
        Map<String, String> headers = createHeaders();
        DateFormat dateFormat = new SimpleDateFormat(LeadSquaredApiConstants.DATE_FORMAT);
        String fromDateString = dateFormat.format(fromDate);
        String toDateString = dateFormat.format(toDate);
        int pageIndex = 1;
        int pageSize = LeadSquaredApiConstants.DEFAULT_PAGE_SIZE;
        int processedRecords = 0;
        int totalRecords = Integer.MAX_VALUE;
        boolean success = true;
        String prospectActivityId = null;
        while (processedRecords < totalRecords) {
            try {
                String body = createActivityPayload(pageIndex, pageSize, fromDateString, toDateString, LeadSquaredApiConstants.ACTIVITY_RAZORPAY_PAYMENT);

                ResponseEntity<Map> r = restUtils.postV2(fetchActivitiesUrl, body, headers);

                try{
                    apiLoggerService.log("Razorpay Activity", fetchActivitiesUrl, body, r.getBody() != null ? r.getBody().toString() : "", r.getStatusCode().toString(), "LeadSquared");
                }catch (Exception e){
                    log.warn("Failed to log Razorpay Activity API call", e);
                }
                Map<String, Object> responseBody = r.getBody();

                totalRecords = (int) responseBody.get(LeadSquaredApiConstants.FIELD_RECORD_COUNT);

                if (responseBody != null) {
                    List<Map<String, Object>> activityList = (List<Map<String, Object>>) responseBody.get(LeadSquaredApiConstants.FIELD_LIST);
                    if (activityList != null) {
                        for (Map<String, Object> activity : activityList) {
                            try {
                                processedRecords++;
                                prospectActivityId = (String) activity.get(LeadSquaredApiConstants.FIELD_PROSPECT_ACTIVITY_ID);
                                LsqRazorpayActivity lsqRazorpayActivity = lsqRazorpayRepository.findByProspectActivityId(prospectActivityId);
                                if(lsqRazorpayActivity==null){
                                    lsqRazorpayActivity = new LsqRazorpayActivity();
                                    lsqRazorpayActivity.setProspectActivityId(prospectActivityId);
                                }
                                lsqRazorpayActivity.setActivityEvent(LeadSquaredApiConstants.ACTIVITY_RAZORPAY_PAYMENT);
                                lsqRazorpayActivity.setActivityEventName(LeadSquaredApiConstants.EVENT_NAME_PAYMENT_PAID);
                                lsqRazorpayActivity.setDisplayName(LeadSquaredApiConstants.DISPLAY_NAME_RAZORPAY);
                                lsqRazorpayActivity.setActivityEventNote((String) activity.get(LeadSquaredApiConstants.FIELD_ACTIVITY_EVENT_NOTE));

                                String relatedProspectId = (String) activity.get(LeadSquaredApiConstants.FIELD_RELATED_PROSPECT_ID);

                                LeadsquaredUser leadsquaredUser = fetchLeadDetails(relatedProspectId);

                                if(leadsquaredUser!=null){

                                    lsqRazorpayActivity.setCustomerName(leadsquaredUser.getFirstName() + " " + leadsquaredUser.getLastName());
                                    lsqRazorpayActivity.setCustomerMobile(leadsquaredUser.getMobile());

                                    lsqRazorpayActivity.setRelatedProspectId(relatedProspectId);

                                    String owner = getLeadOwner((String) activity.get(LeadSquaredApiConstants.FIELD_OWNER));
                                    lsqRazorpayActivity.setOwner(owner);


                                    String status = (String) activity.get(LeadSquaredApiConstants.CUSTOM_RP_PAYMENT_STATUS);
                                    lsqRazorpayActivity.setPaymentStatus(status);

                                    lsqRazorpayActivity.setEvent((String) activity.get(LeadSquaredApiConstants.CUSTOM_RP_EVENT));

                                    Object amountObj = activity.get(LeadSquaredApiConstants.CUSTOM_RP_AMOUNT);
                                    Integer amount = amountObj != null ? Integer.parseInt(amountObj.toString()) : null;
                                    lsqRazorpayActivity.setAmount(amount);

                                    String paymentId = (String) activity.get(LeadSquaredApiConstants.CUSTOM_RP_PAYMENT_ID);
                                    if(paymentId!=null && paymentId.length()>0){
                                        try{
                                            Map<String, String> payeeDetails = razorPayService.fetchPayeeDetails(paymentId);
                                            if(payeeDetails!=null && payeeDetails.get("payeeMobileNumber")!=null && payeeDetails.get("payeeMobileNumber").length()>0){
                                                lsqRazorpayActivity.setCustomerPaymentMobile(payeeDetails.get("payeeMobileNumber"));
                                            }
                                        }catch (Exception e){
                                            log.warn("Failed to fetch payee details for payment {}", paymentId, e);
                                        }
                                    }
                                    lsqRazorpayActivity.setPaymentId(paymentId);
                                    lsqRazorpayActivity.setOrderId((String) activity.get(LeadSquaredApiConstants.CUSTOM_RP_ORDER_ID));
                                    lsqRazorpayActivity.setUpiTransactionId((String) activity.get(LeadSquaredApiConstants.CUSTOM_RP_UPI_TX_ID));
                                    lsqRazorpayActivity.setBankTransactionId((String) activity.get(LeadSquaredApiConstants.CUSTOM_RP_BANK_TX_ID));
                                    lsqRazorpayActivity.setPaymentMethod((String) activity.get(LeadSquaredApiConstants.CUSTOM_RP_PAYMENT_METHOD));
                                    lsqRazorpayActivity.setVirtualPrivateAddress((String) activity.get(LeadSquaredApiConstants.CUSTOM_RP_VPA));

                                    Object taxObj = activity.get(LeadSquaredApiConstants.CUSTOM_RP_TAX);
                                    Integer tax = taxObj != null ? Integer.parseInt(taxObj.toString()) : null;
                                    lsqRazorpayActivity.setTax(tax);

                                    lsqRazorpayActivity.setPaymentStatus((String) activity.get(LeadSquaredApiConstants.CUSTOM_RP_PAYMENT_STATUS));

                                    Object paymentTimeObj = activity.get(LeadSquaredApiConstants.CUSTOM_RP_PAYMENT_TIME);
                                    Date paymentTime = null;
                                    if (paymentTimeObj != null) {
                                        paymentTime = dateFormat.parse(paymentTimeObj.toString());
                                    }
                                    lsqRazorpayActivity.setPaymentTime(paymentTime);
                                    lsqRazorpayRepository.save(lsqRazorpayActivity);
                                }

                            } catch (Exception exc) {
                                log.error("Some exception occurred while processing Lsq Razorpay Activity " + prospectActivityId, exc);
                            }
                        }
                    }
                }
            } catch (Exception ex) {
                success = false;
                log.error("Some exception occurred while fetching batch for activity-22 from LeadSquared", ex);
            }

            log.info("Fetching Razorpay activity: {} out of {}", processedRecords, totalRecords);
            pageIndex++;
        }
        return success;
    }

    public boolean processLsqOwners() throws Exception {
        boolean success = true;

        try{
            String url = getUrl(lsqOwnersUrl);
            ResponseEntity<Object> r = restUtils.get(url);
            Object responseBody = r.getBody();
            if (responseBody != null) {
                List<Map> ownerList = (List<Map>) responseBody;
                if (ownerList != null) {
                    for (Map owner : ownerList) {
                        try{
                            int statusCode = (int)owner.get(LeadSquaredApiConstants.FIELD_OWNER_STATUS_CODE);
                            if(statusCode == LeadSquaredApiConstants.ACTIVE_OWNER_STATUS){
                                LsqOwner lsqOwner = new LsqOwner();
                                lsqOwner.setOwnerId((String)owner.get(LeadSquaredApiConstants.FIELD_OWNER_ID));
                                lsqOwner.setEmailAddress((String)owner.get(LeadSquaredApiConstants.FIELD_OWNER_EMAIL_ADDRESS));
                                lsqOwner.setRole((String)owner.get(LeadSquaredApiConstants.FIELD_OWNER_ROLE));
                                lsqOwner.setFirstName((String)owner.get(LeadSquaredApiConstants.FIELD_FIRST_NAME));
                                lsqOwner.setLastName((String)owner.get(LeadSquaredApiConstants.FIELD_LAST_NAME));
                                lsqOwner.setDateCreated(new Date());
                                lsqOwnerRepository.save(lsqOwner);
                            }
                        }catch (Exception ee){
                            log.error("Some exception occurred while processing owner", ee);
                        }
                    }
                }
            }
        }catch (Exception e){
            log.error("Some exception occurred while fetching lead owners ",e);
            success = false;
        }
        return success;
    }

    @Override
    public ResponseEntity<Object> fetchLeadById(String leadId) throws Exception {
        String url = getUrl(lsqGetLeadByIdUrl) + "&id=" + leadId;
        Map<String, String> headers = new HashMap<>();
        headers.put("Content-Type", "application/json");
        ResponseEntity responseEntity = restUtils.get(url, headers);

        try {
            if (responseEntity.getStatusCode() == HttpStatus.OK && responseEntity.getBody() != null) {
                List<Map<String, Object>> responseList = (List<Map<String, Object>>) responseEntity.getBody();
                if (responseList != null && !responseList.isEmpty()) {
                    Map<String, Object> leadData = responseList.get(0);
                    String prospectId = (String) leadData.get(LeadSquaredApiConstants.FIELD_PROSPECT_ID);

                    Optional<LeadsquaredUser> existingUser = leadsquaredUserRepository.findById(prospectId);
                    if (!existingUser.isPresent()) {
                        LeadsquaredUser newUser = new LeadsquaredUser();
                        newUser.setProspectId(prospectId);
                        newUser.setOwner((String) leadData.get(LeadSquaredApiConstants.FIELD_OWNER_ID_NAME));
                        String firstName = leadData.get(LeadSquaredApiConstants.FIELD_FIRST_NAME) != null ? (String) leadData.get(LeadSquaredApiConstants.FIELD_FIRST_NAME) : "";
                        String lastName = leadData.get(LeadSquaredApiConstants.FIELD_LAST_NAME) != null ? (String) leadData.get(LeadSquaredApiConstants.FIELD_LAST_NAME) : "";
                        newUser.setFirstName((firstName).trim());
                        newUser.setLastName((lastName).trim());
                        newUser.setMobile((String) leadData.get(LeadSquaredApiConstants.FIELD_PHONE));

                        String createdOnStr = (String) leadData.get(LeadSquaredApiConstants.FIELD_CREATED_ON);
                        if (createdOnStr != null) {
                            DateFormat dateFormat = new SimpleDateFormat(LeadSquaredApiConstants.DATE_FORMAT);
                            newUser.setCreatedOn(dateFormat.parse(createdOnStr));
                        }

                        leadsquaredUserRepository.save(newUser);
                        log.info("Saved new LeadsquaredUser for leadId: " + leadId);
                    } else {
                        log.info("LeadsquaredUser already exists for leadId: " + leadId);
                    }
                }
            }
        } catch (Exception e) {
            log.error("Error while processing LeadsquaredUser for leadId: " + leadId, e);
        }

        return responseEntity;
    }

    String getUrl(String url){
        if(url!=null){
            url+="?accessKey="+lsqAccessKey+"&secretKey="+lsqSecretKey;
        }
        return url;
    }

    public String getLeadOwner(String leadId){
        LsqOwner leadOwnerDocument = lsqOwnerRepository.findByOwnerId(leadId);
        String leadEmail = null;
        if (leadOwnerDocument!=null){
            leadEmail = leadOwnerDocument.getEmailAddress();
        }
        else {
            leadEmail = leadId;
        }
        return leadEmail;
    }

    private String createActivityPayload(int pageIndex, int pageSize, String fromDateString, String toDateString, String activityId) {
        String payload = "{\n" +
                "\"Parameter\": {\n" +
                "\"FromDate\": \"" + fromDateString + "\",\n" +
                "\"ToDate\": \"" + toDateString + "\",\n" +
                "\"ActivityEvent\": \"" + activityId + "\",\n" +
                "\"RemoveEmptyValue\": true\n" +
                "},\n" +
                "\"Paging\": {\n" +
                "\"PageIndex\": " + pageIndex + ",\n" +
                "\"PageSize\": " + pageSize + "\n" +
                "},\n" +
                "\"Sorting\": {\n" +
                "\"ColumnName\": \"" + LeadSquaredApiConstants.SORT_COLUMN_MODIFIED_ON + "\",\n" +
                "\"Direction\": 1\n" +
                "}\n" +
                "}";
        return payload;
    }

    private Map<String, String> createHeaders(){
        Map<String, String> headers = new HashMap<>();
        headers.put(LeadSquaredApiConstants.HEADER_ACCESS_KEY, lsqAccessKey);
        headers.put(LeadSquaredApiConstants.HEADER_SECRET_KEY, lsqSecretKey);
        return headers;
    }

    private LeadsquaredUser fetchLeadDetails(String leadId) {
        if (leadId == null) return null;

        LeadsquaredUser leadsquaredUser = leadsquaredUserRepository.findByProspectId(leadId);
        if (leadsquaredUser != null) {
            return leadsquaredUser;
        } else {
            try {
                fetchLeadById(leadId);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
            leadsquaredUser = leadsquaredUserRepository.findByProspectId(leadId);
        }
        return leadsquaredUser;
    }

    public boolean processLsqPaymentLinkActivity(Date fromDate, Date toDate) throws Exception {
