    private final RestUtils restUtils;
    private final APILoggerService apiLoggerService;
    private final StateCodeMappingRepository stateCodeMappingRepository;
    private final DistrictPlantCodeMappingRepository districtPlantCodeMappingRepository;

    @Override
    public SapCreateResponse createCustomer(LeadSapRequest request) {
        log.info("Creating SAP customer for prospectId: {}", request.getProspectId());

        Map<String, String> headers = new HashMap<>();
        headers.put("Authorization", sapAuthorization);
        Map<String, Object> payload = createPayload(request);

        ObjectMapper mapper = new ObjectMapper();
        String jsonBody;
        try {
            jsonBody = mapper.writeValueAsString(payload);
        } catch (JsonProcessingException e) {
            throw new IntegrationException("Failed to serialize SAP payload", e);
        }

        Map<String, Object> responseBody = null;
        String statusCode = "";
        try {
            ResponseEntity<Map> response = restUtils.postV2(sapApiUrl, jsonBody, headers);
            statusCode = String.valueOf(response.getStatusCodeValue());
            if (response.getStatusCode().is2xxSuccessful()) {
                log.info("Successfully created SAP customer. Response: {}", response.getBody());
                responseBody = response.getBody();
            }
        } catch (Exception e) {
            log.error("Error calling SAP API", e);
        }

        apiLoggerService.log("Create Customer", sapApiUrl, jsonBody, responseBody != null ? responseBody.toString() : "", statusCode, "SAP");
        return parseSapResponse(responseBody);
    }

    private SapCreateResponse parseSapResponse(Map<String, Object> responseBody) {
        if (responseBody == null) return null;
        int status = responseBody.get("status") != null ? (int) responseBody.get("status") : -1;
        String changeNumber = null;
        if (status == 0 && responseBody.get("Record") != null) {
            Map<String, String> record = (Map<String, String>) responseBody.get("Record");
            changeNumber = record.get("Change_Number");
        }
        return SapCreateResponse.builder()
                .status(status)
                .changeNumber(changeNumber)
                .build();
    }

    private Map<String, Object> createPayload(LeadSapRequest request) {
        Map<String, Object> record = new HashMap<>();
        record.put("Dist_Channel", "16");
        record.put("Divison", 16);

        Map<String, Object> generalData = new HashMap<>();
        generalData.put("SAPCustomerID", "");
        generalData.put("Title", "");
        generalData.put("firstName", request.getName() != null ? request.getName() : "");
        generalData.put("lastName", "");
        String mobile = Utils.transformMobileNumber(request.getMobile() != null ? request.getMobile() : "");
        generalData.put("mobile", mobile);
        generalData.put("username", request.getEmail() != null ? request.getEmail() : "");
        generalData.put("address", request.getAddress() != null ? request.getAddress() : "");
        generalData.put("pinCode", request.getPincode() != null ? request.getPincode() : "");
        generalData.put("city", request.getCity() != null ? request.getCity() : "");
        String stateCode = getStateCode(request.getState() != null ? request.getState() : "");
        generalData.put("state", stateCode);
        generalData.put("country", "IN");
        generalData.put("GSTN", request.getPan() != null ? request.getPan() : "");
        generalData.put("BU_SORT1_TXT", "SOLAR360");
        record.put("General_Data", generalData);

        Map<String, Object> companyCodeData = new HashMap<>();
        companyCodeData.put("Recon_acc", "104100006");
        companyCodeData.put("Payment_terms", "Z001");
        record.put("Company_code_Data", companyCodeData);

        Map<String, Object> salesAreaData = new HashMap<>();
