    private LeadsquaredUser fetchLeadDetails(String leadId) {
        if (leadId == null) return null;

        LeadsquaredUser leadsquaredUser = leadsquaredUserRepository.findByProspectId(leadId);
        if (leadsquaredUser != null) {
            return leadsquaredUser;
        } else {
            try {
                fetchLeadById(leadId);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
            leadsquaredUser = leadsquaredUserRepository.findByProspectId(leadId);
        }
        return leadsquaredUser;
    }

    public boolean processLsqPaymentLinkActivity(Date fromDate, Date toDate) throws Exception {
        String fetchActivitiesUrl = lsqActivityUrl;
        Map<String, String> headers = createHeaders();
        DateFormat dateFormat = new SimpleDateFormat(LeadSquaredApiConstants.DATE_FORMAT);
        String fromDateString = dateFormat.format(fromDate);
        String toDateString = dateFormat.format(toDate);
        int pageIndex = 1;
        int pageSize = LeadSquaredApiConstants.DEFAULT_PAGE_SIZE;
        int processedRecords = 0;
        int totalRecords = Integer.MAX_VALUE;
        boolean success = true;
        String prospectActivityId = null;
        while (processedRecords < totalRecords) {
            try {
                String body = createActivityPayload(pageIndex, pageSize, fromDateString, toDateString, LeadSquaredApiConstants.ACTIVITY_PAYMENT_LINK);
                ResponseEntity<Map> r = restUtils.postV2(fetchActivitiesUrl, body, headers);

                try{
                    apiLoggerService.log("Payment Link Activity", fetchActivitiesUrl, body, r.getBody() != null ? r.getBody().toString() : "", r.getStatusCode().toString(), "LeadSquared");
                }catch (Exception e){
                    log.warn("Failed to log Payment Link Activity API call", e);
                }
                Map<String, Object> responseBody = r.getBody();

                totalRecords = (int) responseBody.get(LeadSquaredApiConstants.FIELD_RECORD_COUNT);

                if (responseBody != null) {
                    List<Map<String, Object>> activityList = (List<Map<String, Object>>) responseBody.get(LeadSquaredApiConstants.FIELD_LIST);
                    if (activityList != null) {
                        for (Map<String, Object> activity : activityList) {
                            try {
                                processedRecords++;
                                prospectActivityId = (String) activity.get(LeadSquaredApiConstants.FIELD_PROSPECT_ACTIVITY_ID);
                                LsqPaymentLinkActivity lsqPaymentLinkActivity = lsqPaymentLinkRepository.findByProspectActivityId(prospectActivityId);
                                if(lsqPaymentLinkActivity==null){
                                    lsqPaymentLinkActivity = new LsqPaymentLinkActivity();
                                    lsqPaymentLinkActivity.setProspectActivityId(prospectActivityId);
                                }
                                lsqPaymentLinkActivity.setActivityEvent(LeadSquaredApiConstants.ACTIVITY_PAYMENT_LINK);
                                lsqPaymentLinkActivity.setActivityEventName(LeadSquaredApiConstants.EVENT_NAME_PAYMENT_LINK);
                                lsqPaymentLinkActivity.setDisplayName(LeadSquaredApiConstants.EVENT_NAME_PAYMENT_LINK);
                                lsqPaymentLinkActivity.setActivityEventNote((String) activity.get(LeadSquaredApiConstants.FIELD_ACTIVITY_EVENT_NOTE));

                                String relatedProspectId = (String) activity.get(LeadSquaredApiConstants.FIELD_RELATED_PROSPECT_ID);

                                LeadsquaredUser leadsquaredUser = fetchLeadDetails(relatedProspectId);

                                if(leadsquaredUser!=null){

                                    lsqPaymentLinkActivity.setLsqLeadName(leadsquaredUser.getFirstName() + " " + leadsquaredUser.getLastName());
                                    lsqPaymentLinkActivity.setLsqLeadMobile(leadsquaredUser.getMobile());
                                }
                                lsqPaymentLinkActivity.setRelatedProspectId(relatedProspectId);

                                Object amountObj = activity.get(LeadSquaredApiConstants.CUSTOM_PL_AMOUNT);
                                Integer amount = amountObj != null ? Integer.parseInt(amountObj.toString()) : null;
                                lsqPaymentLinkActivity.setAmount(amount);

                                lsqPaymentLinkActivity.setPaymentLinkId((String) activity.get(LeadSquaredApiConstants.CUSTOM_PL_PAYMENT_LINK_ID));
                                lsqPaymentLinkActivity.setCurrency((String) activity.get(LeadSquaredApiConstants.CUSTOM_PL_CURRENCY));
                                lsqPaymentLinkRepository.save(lsqPaymentLinkActivity);

                            } catch (Exception exc) {
                                log.error("Some exception occurred while processing Lsq Payment Link Activity " + prospectActivityId, exc);
                            }
                        }
                    }
                }
            } catch (Exception ex) {
                success = false;
                log.error("Some exception occurred while fetching batch for activity-22 from LeadSquared", ex);
            }

            log.info("Fetching payment link activity: {} out of {}", processedRecords, totalRecords);
            pageIndex++;
        }
        return success;
    }

    private String extractDestinationNumber(String activityNote) {
        // If the input is null or doesn't have the key, skip
        if (activityNote == null || !activityNote.contains("DestinationNumber")) return null;

        // Find the start index of the value
        int start = activityNote.indexOf("DestinationNumber\":\"");
        if (start == -1) return null;

        // Move the index just past the key string to the start of the value
        start += "DestinationNumber\":\"".length();

        // Find the closing quote of the value
        int end = activityNote.indexOf("\"", start);
        if (end == -1) return null;

        // Return the substring containing just the destination number
        return activityNote.substring(start, end);
    }

}

package com.integration.service.impl;

import com.integration.model.RazorpaySettlement;
import com.integration.repository.RazorpaySettlementRepository;
import com.integration.service.APILoggerService;
import com.integration.service.RazorPayService;
import com.integration.util.RestUtils;
import lombok.RequiredArgsConstructor;
import lombok.extern.log4j.Log4j2;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Service;

import java.util.Base64;
import java.util.Date;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

@Service
@Log4j2
@RequiredArgsConstructor
public class RazorPayServiceImpl implements RazorPayService {

    private final RestUtils restUtils;
    private final APILoggerService apiLoggerService;
    private final RazorpaySettlementRepository razorpaySettlementRepository;

    @Value("${razorpay.key.id}")
    private String razorpayKeyId;

    @Value("${razorpay.key.secret}")
    private String razorpayKeySecret;

    private static final String RAZORPAY_RECON_URL = "https://api.razorpay.com/v1/settlements/recon/combined";
    private static final String RAZORPAY_PAYMENT_LINK_URL = "https://api.razorpay.com/v1/payment_links/";
    private static final String RAZORPAY_PAYMENT_URL = "https://api.razorpay.com/v1/payments/";

    private String getAuthHeader() {
        return "Basic " + Base64.getEncoder().encodeToString((razorpayKeyId + ":" + razorpayKeySecret).getBytes());
    }

    @Override
    public boolean getSettlementsReconCombined(String year, String month, String day) throws Exception {
        boolean success = false;
        String url = String.format("%s?year=%s&month=%s&day=%s", RAZORPAY_RECON_URL, year, month, day);

        Map<String, String> headers = new HashMap<>();
        headers.put("Authorization", getAuthHeader());

        try {
            ResponseEntity<?> response = restUtils.get(url, headers);
            try{
                String statusCode = String.valueOf(response.getStatusCodeValue());
                String logResponse = response.getBody() != null ? response.getBody().toString() : "";
                apiLoggerService.log("Settlement", url, "", logResponse, statusCode, "Razorpay");
            }catch (Exception e){
                log.warn("Failed to log Settlement API call", e);
            }
            if (response.getBody() instanceof Map) {
                Map<String, Object> body = (Map<String, Object>) response.getBody();

                if (body.containsKey("items") && body.get("items") instanceof List) {
                    List<Map<String, Object>> items = (List<Map<String, Object>>) body.get("items");

                    items.forEach(item -> {
                        try{
                            String entityId = (String) item.get("entity_id");
                            RazorpaySettlement razorpaySettlement = razorpaySettlementRepository.findByPaymentId(entityId);
                            if(razorpaySettlement==null){
                                razorpaySettlement = new RazorpaySettlement();
                                razorpaySettlement.setPaymentId(entityId);
                            }
                            razorpaySettlement.setSettlementId((String) item.get("settlement_id"));
                            razorpaySettlement.setOrderId( (String) item.get("order_id"));
                            razorpaySettlement.setAmount( item.get("amount") != null ? ((Number) item.get("amount")).intValue() / 100 : 0);
                            razorpaySettlement.setCredit( item.get("credit") != null ? ((Number) item.get("credit")).intValue() / 100 : 0);
                            razorpaySettlement.setFee( item.get("fee") != null ? ((Number) item.get("fee")).intValue() / 100 : 0);
                            razorpaySettlement.setTax( item.get("tax") != null ? ((Number) item.get("tax")).intValue() / 100 : 0);
                            razorpaySettlement.setSettlementUtr( (String) item.get("settlement_utr"));
                            razorpaySettlement.setNotes( (String) item.get("notes"));
                            razorpaySettlement.setDescription( (String) item.get("description"));
                            razorpaySettlement.setSettled( (Boolean) item.get("settled"));
                            razorpaySettlement.setSettledAt( item.get("settled_at") != null ? new Date(((Number) item.get("settled_at")).longValue() * 1000) : null);
                            razorpaySettlement.setCreatedAt( item.get("created_at") != null ? new Date(((Number) item.get("created_at")).longValue() * 1000) : null);
                            razorpaySettlementRepository.save(razorpaySettlement);
                        } catch (Exception e) {
                            log.error("Error processing settlement item", e);
                        }
                    });
                }
            }
           success = true;
        } catch (Exception e) {
            log.error("Error calling RazorPay API: {}", e.getMessage());
            throw e;
        }
        return success;
    }

    @Override
    public ResponseEntity<?> fetchPaymentLinkDetails(String paymentLinkId) throws Exception {
        String url = RAZORPAY_PAYMENT_LINK_URL + paymentLinkId;
        Map<String, String> headers = new HashMap<>();
        headers.put("Authorization", getAuthHeader());
        headers.put("Content-Type", "application/json");

        try {
            ResponseEntity<?> response = restUtils.get(url, headers);
            try{
                String statusCode = String.valueOf(response.getStatusCodeValue());
                String logResponse = response.getBody() != null ? response.getBody().toString() : "";
                apiLoggerService.log("Payment Link", url, "", logResponse, statusCode, "Razorpay");
            }catch (Exception e){
                log.warn("Failed to log Payment Link API call", e);
            }
            return response;
        } catch (Exception e) {
            log.error("Error calling RazorPay API for payment link {}: {}", paymentLinkId, e.getMessage());
            throw e;
        }
    }

    @Override
    public ResponseEntity<?> fetchPaymentDetails(String paymentId) throws Exception {
        String url = RAZORPAY_PAYMENT_URL + paymentId;
        Map<String, String> headers = new HashMap<>();
        headers.put("Authorization", getAuthHeader());
        headers.put("Content-Type", "application/json");

        try {
            ResponseEntity<?> response = restUtils.get(url, headers);
            try{
                String statusCode = String.valueOf(response.getStatusCodeValue());
                String logResponse = response.getBody() != null ? response.getBody().toString() : "";
                apiLoggerService.log("Payment Detail", url, "", logResponse, statusCode, "Razorpay");
            }catch (Exception e){
                log.warn("Failed to log Payment Detail API call", e);
            }
            return response;
        } catch (Exception e) {
            log.error("Error calling RazorPay API for payment {}: {}", paymentId, e.getMessage());
            throw e;
        }
    }

    @Override
    public Map<String, String> fetchPayeeDetails(String paymentId) throws Exception {
        Map<String, String> payeeDetails = new HashMap<>();
        payeeDetails.put("payeeMobileNumber","");
        try {
            ResponseEntity<?> response = fetchPaymentDetails(paymentId);
            Map<String, Object> body = (Map<String, Object>) response.getBody();
            String payeeMobileNumber = (String) body.get("contact");
            payeeDetails.put("payeeMobileNumber", payeeMobileNumber);
            return payeeDetails;
        } catch (Exception e) {
            log.error("Error fetching payee details for payment {}", paymentId, e);
        }
        return null;
    }

}

