                ResponseEntity<Map> r = restUtils.postV2(lsqActivityUrl, body, headers);
                try {
                    apiLoggerService.log("Payment Link Activity", lsqActivityUrl, body, r.getBody() != null ? r.getBody().toString() : "", r.getStatusCode().toString(), "LeadSquared");
                } catch (Exception e) {
                    log.warn("Failed to log Payment Link Activity API call", e);
