            }

            log.info("Fetching payment link activity: {} out of {}", processedRecords, totalRecords);
            pageIndex++;
        }
        return success;
    }

    @Override
    public ResponseEntity<Object> fetchLeadById(String leadId) {
        String url = buildAuthUrl(lsqGetLeadByIdUrl) + "&id=" + leadId;
        Map<String, String> headers = new HashMap<>();
        headers.put("Content-Type", "application/json");
        ResponseEntity responseEntity = restUtils.get(url, headers);

        try {
            if (responseEntity.getStatusCode() == HttpStatus.OK && responseEntity.getBody() != null) {
                List<Map<String, Object>> responseList = (List<Map<String, Object>>) responseEntity.getBody();
                if (responseList != null && !responseList.isEmpty()) {
                    Map<String, Object> leadData = responseList.get(0);
                    String prospectId = (String) leadData.get(LeadSquaredApiConstants.FIELD_PROSPECT_ID);

                    Optional<LeadsquaredUser> existingUser = leadsquaredUserRepository.findById(prospectId);
                    if (!existingUser.isPresent()) {
                        LeadsquaredUser newUser = new LeadsquaredUser();
                        newUser.setProspectId(prospectId);
                        newUser.setOwner((String) leadData.get(LeadSquaredApiConstants.FIELD_OWNER_ID_NAME));
                        String firstName = leadData.get(LeadSquaredApiConstants.FIELD_FIRST_NAME) != null ? (String) leadData.get(LeadSquaredApiConstants.FIELD_FIRST_NAME) : "";
                        String lastName = leadData.get(LeadSquaredApiConstants.FIELD_LAST_NAME) != null ? (String) leadData.get(LeadSquaredApiConstants.FIELD_LAST_NAME) : "";
                        newUser.setFirstName(firstName.trim());
                        newUser.setLastName(lastName.trim());
                        newUser.setMobile((String) leadData.get(LeadSquaredApiConstants.FIELD_PHONE));

                        String createdOnStr = (String) leadData.get(LeadSquaredApiConstants.FIELD_CREATED_ON);
                        if (createdOnStr != null) {
                            DateFormat dateFormat = new SimpleDateFormat(LeadSquaredApiConstants.DATE_FORMAT);
                            newUser.setCreatedOn(dateFormat.parse(createdOnStr));
                        }
                        leadsquaredUserRepository.save(newUser);
                        log.info("Saved new LeadsquaredUser for leadId: {}", leadId);
                    } else {
                        log.info("LeadsquaredUser already exists for leadId: {}", leadId);
                    }
                }
            }
        } catch (Exception e) {
            log.error("Error processing LeadsquaredUser for leadId: {}", leadId, e);
        }

        return responseEntity;
    }

    private LeadsquaredUser fetchLeadDetails(String leadId) {
        if (leadId == null) return null;
        LeadsquaredUser user = leadsquaredUserRepository.findByProspectId(leadId);
        if (user != null) return user;
        try {
            fetchLeadById(leadId);
        } catch (Exception e) {
            log.warn("Failed to fetch lead details for leadId: {}", leadId, e);
        }
        return leadsquaredUserRepository.findByProspectId(leadId);
    }

    private Map<String, String> createHeaders() {
        Map<String, String> headers = new HashMap<>();
        headers.put(LeadSquaredApiConstants.HEADER_ACCESS_KEY, lsqAccessKey);
        headers.put(LeadSquaredApiConstants.HEADER_SECRET_KEY, lsqSecretKey);
        return headers;
    }

    private String buildAuthUrl(String url) {
        if (url == null) return null;
        return url + "?accessKey=" + lsqAccessKey + "&secretKey=" + lsqSecretKey;
    }

    private String createActivityPayload(int pageIndex, int pageSize, String fromDateString, String toDateString, String activityId) {
        return "{\n" +
                "\"Parameter\": {\n" +
                "\"FromDate\": \"" + fromDateString + "\",\n" +
                "\"ToDate\": \"" + toDateString + "\",\n" +
                "\"ActivityEvent\": \"" + activityId + "\",\n" +
                "\"RemoveEmptyValue\": true\n" +
                "},\n" +
                "\"Paging\": {\n" +
                "\"PageIndex\": " + pageIndex + ",\n" +
                "\"PageSize\": " + pageSize + "\n" +
                "},\n" +
                "\"Sorting\": {\n" +
                "\"ColumnName\": \"" + LeadSquaredApiConstants.SORT_COLUMN_MODIFIED_ON + "\",\n" +
                "\"Direction\": 1\n" +
                "}\n" +
                "}";
    }
}

