    78→    private Map<String, Object> prepareLeadUpdateData(List<Map<String, String>> sapCustomerList) {
    79→        Map<String, Object> leadUpdate = new HashMap<>();
    80→        leadUpdate.put("SearchByKey", "ProspectId");
    81→
    82→        List<Map<String, Object>> leadPropertiesList = new ArrayList<>();
    83→        for (Map<String, String> sapCustomer : sapCustomerList) {
    84→            Map<String, Object> leadPropertyEntry = new HashMap<>();
    85→            List<Map<String, String>> fields = new ArrayList<>();
    86→
    87→            Map<String, String> prospectIdField = new HashMap<>();
    88→            prospectIdField.put("Attribute", "ProspectID");
    89→            prospectIdField.put("Value", sapCustomer.get("prospectId"));
    90→            fields.add(prospectIdField);
    91→
    92→            Map<String, String> customerCodeField = new HashMap<>();
    93→            customerCodeField.put("Attribute", "mx_Customer_Code");
    94→            customerCodeField.put("Value", sapCustomer.get("customerCode"));
    95→            fields.add(customerCodeField);
    96→
    97→            leadPropertyEntry.put("Fields", fields);
    98→            leadPropertiesList.add(leadPropertyEntry);
    99→        }
   100→        leadUpdate.put("LeadPropertiesList", leadPropertiesList);
   101→        return leadUpdate;
